#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/irq_offload.h>

#define MSG_SIZE 8
#define MSG_COUNT 1

K_MSGQ_DEFINE(kmsgq_empty, MSG_SIZE, MSG_COUNT, 4);
K_MSGQ_DEFINE(kmsgq_full, MSG_SIZE, MSG_COUNT, 4);

static char __aligned(4) rx_msg[MSG_SIZE];
static char __aligned(4) tx_msg[MSG_SIZE] = "test";

static void isr_get_empty_entry(const void *p)
{
	int ret;
	struct k_msgq *msgq = (struct k_msgq *)p;

	/* Should fail because of K_NO_WAIT */
	ret = k_msgq_get(msgq, &rx_msg, K_NO_WAIT);
	zassert_equal(ret, -ENOMSG, "get from empty msgq should have failed");
}

static void get_empty_entry(void *p1, void *p2, void *p3)
{
	int ret;
	struct k_msgq *msgq = p1;
	k_timeout_t timeout = Z_TIMEOUT_TICKS((uintptr_t)p3);

	ret = k_msgq_get(msgq, &rx_msg, timeout);
	if (K_TIMEOUT_EQ(timeout, K_NO_WAIT)) {
		zassert_equal(ret, -ENOMSG,
			      "get from empty msgq should have failed");
	} else {
		zassert_equal(ret, -EAGAIN,
			      "get from empty msgq should have timed out");
	}
}

/**
 * @brief Test getting messages from an empty message queue
 *
 * @ingroup kernel_msgq_tests
 *
 * @see k_msgq_get()
 */
ZTEST(msgq_api_1cpu, test_msgq_empty)
{
	/* Test thread context */
	/* Should fail because of K_NO_WAIT */
	get_empty_entry(&kmsgq_empty, NULL, (void *)0);
	/* Should fail because of timeout */
	get_empty_entry(&kmsgq_empty, NULL, (void *)1);

	/* Test ISR context */
	irq_offload(isr_get_empty_entry, &kmsgq_empty);
}

static void isr_put_full_entry(const void *p)
{
	int ret;
	struct k_msgq *msgq = (struct k_msgq *)p;

	/* Should fail because of K_NO_WAIT */
	ret = k_msgq_put(msgq, &tx_msg, K_NO_WAIT);
	zassert_equal(ret, -EAGAIN, "put to full msgq should have failed");
}

static void put_full_entry(void *p1, void *p2, void *p3)
{
	int ret;
	struct k_msgq *msgq = p1;
	char *data = p2;
	k_timeout_t timeout = Z_TIMEOUT_TICKS((uintptr_t)p3);

	ret = k_msgq_put(msgq, data, timeout);
	if (K_TIMEOUT_EQ(timeout, K_NO_WAIT)) {
		zassert_equal(ret, -EAGAIN,
			      "put on full msgq should have failed with -EAGAIN");
	} else {
		zassert_equal(ret, -ENOMSG,
			      "put on full msgq should have timed out");
	}
}

/**
 * @brief Test putting messages into a full message queue
 *
 * @ingroup kernel_msgq_tests
 *
 * @see k_msgq_put()
 */
ZTEST(msgq_api_1cpu, test_msgq_full)
{
	int ret;

	/* Fill the message queue */
	ret = k_msgq_put(&kmsgq_full, &tx_msg, K_NO_WAIT);
	zassert_equal(ret, 0, "put to empty msgq failed");

	/* Test thread context */
	/* Should fail because of K_NO_WAIT */
	put_full_entry(&kmsgq_full, &tx_msg, (void *)0);
	/* Should fail because of timeout */
	put_full_entry(&kmsgq_full, &tx_msg, (void *)1);

	/* Test ISR context */
	irq_offload(isr_put_full_entry, &kmsgq_full);
}
